  const betaPlatforms = platforms.filter((p) => p.beta).map((p) => p.name).filter((name) => name !== void 0);
  const deprecatedPlatforms = platforms.filter((p) => p.deprecated).map((p) => p.name).filter((name) => name !== void 0);
